#[tokio::test]
async fn test_validation_ssrf_allowlisted_loopback() {
    // SSRF allowlist permits a loopback mock server while private-network protection remains enabled
    let engine_config: CrawlConfig = serde_json::from_str("{\"respect_robots_txt\":false,\"ssrf\":{\"allowlist\":[{\"type\":\"cidr\",\"value\":\"127.0.0.0/8\"}],\"deny_private\":true,\"max_redirects\":5},\"ssrf_deny_private_explicit\":true}").expect("config should parse");
    let engine = create_engine(Some(engine_config)).expect("handle creation should succeed");
    let url = std::env::var("MOCK_SERVER_VALIDATION_SSRF_ALLOWLISTED_LOOPBACK").unwrap_or_else(|_| {
        let _ = common::mock_server_url();
        std::env::var("MOCK_SERVER_VALIDATION_SSRF_ALLOWLISTED_LOOPBACK").unwrap_or_else(|_| {
            format!(
                "{}/fixtures/{}",
                common::mock_server_url(),
                "validation_ssrf_allowlisted_loopback"
            )
        })
    });
    let result = scrape(&engine, &url).await.expect("call failed");
    let _metadata_title = result
        .metadata
        .title
        .as_ref()
        .map(|v| v.to_string())
        .unwrap_or_default();
    assert_eq!(result.status_code, 200, "equals assertion failed");
    assert_eq!(_metadata_title.to_string(), r#"Allowlisted"#, "equals assertion failed");
}

